-- READ-ONLY exact-key and nearest 300-second target check for legacy rows in existing gap windows.
SELECT o.gap_id, COUNT(*) AS old_source_rows, SUM(w.`dateTime` IS NOT NULL) AS exact_wh1080_matches, SUM(z.`dateTime` IS NOT NULL) AS exact_eu_old_matches, SUM(r.`dateTime` IS NOT NULL) AS exact_reconstruction_matches, SUM(MOD(o.`dateTime`,300)=0) AS on_300s_grid, SUM(MOD(o.`dateTime`,300)<>0) AS off_300s_grid, COUNT(DISTINCT (o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0))) AS distinct_nearest_300s_slots, COUNT(*)-COUNT(DISTINCT (o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0))) AS source_projection_collisions, SUM(rp.`dateTime` IS NOT NULL) AS rows_projecting_to_occupied_reconstruction_slots, SUM(NOT (o.`outTemp` <=> w.`outTemp`)) AS outTemp_old_wh_conflicts, SUM(NOT (o.`outTemp` <=> z.`outTemp`)) AS outTemp_old_euold_conflicts, SUM(NOT (o.`outHumidity` <=> w.`outHumidity`)) AS outHumidity_old_wh_conflicts, SUM(NOT (o.`outHumidity` <=> z.`outHumidity`)) AS outHumidity_old_euold_conflicts, SUM(NOT (o.`rain` <=> w.`rain`)) AS rain_old_wh_conflicts, SUM(NOT (o.`rain` <=> z.`rain`)) AS rain_old_euold_conflicts, SUM(NOT (o.`rainRate` <=> w.`rainRate`)) AS rainRate_old_wh_conflicts, SUM(NOT (o.`rainRate` <=> z.`rainRate`)) AS rainRate_old_euold_conflicts, SUM(NOT (o.`windSpeed` <=> w.`windSpeed`)) AS windSpeed_old_wh_conflicts, SUM(NOT (o.`windSpeed` <=> z.`windSpeed`)) AS windSpeed_old_euold_conflicts, SUM(NOT (o.`windGust` <=> w.`windGust`)) AS windGust_old_wh_conflicts, SUM(NOT (o.`windGust` <=> z.`windGust`)) AS windGust_old_euold_conflicts, SUM(NOT (o.`windDir` <=> w.`windDir`)) AS windDir_old_wh_conflicts, SUM(NOT (o.`windDir` <=> z.`windDir`)) AS windDir_old_euold_conflicts, SUM(NOT (o.`barometer` <=> w.`barometer`)) AS barometer_old_wh_conflicts, SUM(NOT (o.`barometer` <=> z.`barometer`)) AS barometer_old_euold_conflicts, SUM(NOT (o.`pressure` <=> w.`pressure`)) AS pressure_old_wh_conflicts, SUM(NOT (o.`pressure` <=> z.`pressure`)) AS pressure_old_euold_conflicts, SUM(NOT (o.`altimeter` <=> w.`altimeter`)) AS altimeter_old_wh_conflicts, SUM(NOT (o.`altimeter` <=> z.`altimeter`)) AS altimeter_old_euold_conflicts, SUM(o.`usUnits`<>w.`usUnits`) AS usUnits_old_wh_conflicts, SUM(o.`interval`<>w.`interval`) AS interval_old_wh_conflicts, SUM(o.`usUnits`<>z.`usUnits`) AS usUnits_old_euold_conflicts, SUM(o.`interval`<>z.`interval`) AS interval_old_euold_conflicts FROM (SELECT CASE WHEN `dateTime`>1330952700 AND `dateTime`<1330965900 THEN 1 WHEN `dateTime`>1331404500 AND `dateTime`<1331412300 THEN 2 WHEN `dateTime`>1331412300 AND `dateTime`<1331417700 THEN 3 WHEN `dateTime`>1331418900 AND `dateTime`<1331426700 THEN 4 WHEN `dateTime`>1333907100 AND `dateTime`<1333922700 THEN 5 WHEN `dateTime`>1338749700 AND `dateTime`<1338759000 THEN 6 WHEN `dateTime`>1340367900 AND `dateTime`<1340374200 THEN 7 WHEN `dateTime`>1341100500 AND `dateTime`<1341106500 THEN 8 WHEN `dateTime`>1342207800 AND `dateTime`<1342213200 THEN 9 WHEN `dateTime`>1344996600 AND `dateTime`<1345019400 THEN 10 WHEN `dateTime`>1346451900 AND `dateTime`<1346457600 THEN 11 WHEN `dateTime`>1347913200 AND `dateTime`<1347921900 THEN 12 WHEN `dateTime`>1348474200 AND `dateTime`<1348480200 THEN 13 WHEN `dateTime`>1348480200 AND `dateTime`<1348485000 THEN 14 WHEN `dateTime`>1348485000 AND `dateTime`<1348492200 THEN 15 WHEN `dateTime`>1348494000 AND `dateTime`<1348520400 THEN 16 WHEN `dateTime`>1348576200 AND `dateTime`<1348581600 THEN 17 WHEN `dateTime`>1348789800 AND `dateTime`<1348794000 THEN 18 WHEN `dateTime`>1349437500 AND `dateTime`<1349442300 THEN 19 WHEN `dateTime`>1350296400 AND `dateTime`<1350301200 THEN 20 WHEN `dateTime`>1350758700 AND `dateTime`<1350765000 THEN 21 WHEN `dateTime`>1352101500 AND `dateTime`<1352108400 THEN 22 WHEN `dateTime`>1354703400 AND `dateTime`<1354711200 THEN 23 WHEN `dateTime`>1354735200 AND `dateTime`<1354740000 THEN 24 WHEN `dateTime`>1354808400 AND `dateTime`<1354813200 THEN 25 WHEN `dateTime`>1355184900 AND `dateTime`<1355189700 THEN 26 WHEN `dateTime`>1355189700 AND `dateTime`<1355205300 THEN 27 WHEN `dateTime`>1355205300 AND `dateTime`<1355230500 THEN 28 WHEN `dateTime`>1356963900 AND `dateTime`<1356969900 THEN 29 ELSE NULL END AS gap_id, `dateTime`, `outTemp`, `outHumidity`, `rain`, `rainRate`, `windSpeed`, `windGust`, `windDir`, `barometer`, `pressure`, `altimeter`, `usUnits`, `interval` FROM `old_weewx`.`archive` WHERE (`dateTime`>1330952700 AND `dateTime`<1330965900) OR (`dateTime`>1331404500 AND `dateTime`<1331412300) OR (`dateTime`>1331412300 AND `dateTime`<1331417700) OR (`dateTime`>1331418900 AND `dateTime`<1331426700) OR (`dateTime`>1333907100 AND `dateTime`<1333922700) OR (`dateTime`>1338749700 AND `dateTime`<1338759000) OR (`dateTime`>1340367900 AND `dateTime`<1340374200) OR (`dateTime`>1341100500 AND `dateTime`<1341106500) OR (`dateTime`>1342207800 AND `dateTime`<1342213200) OR (`dateTime`>1344996600 AND `dateTime`<1345019400) OR (`dateTime`>1346451900 AND `dateTime`<1346457600) OR (`dateTime`>1347913200 AND `dateTime`<1347921900) OR (`dateTime`>1348474200 AND `dateTime`<1348480200) OR (`dateTime`>1348480200 AND `dateTime`<1348485000) OR (`dateTime`>1348485000 AND `dateTime`<1348492200) OR (`dateTime`>1348494000 AND `dateTime`<1348520400) OR (`dateTime`>1348576200 AND `dateTime`<1348581600) OR (`dateTime`>1348789800 AND `dateTime`<1348794000) OR (`dateTime`>1349437500 AND `dateTime`<1349442300) OR (`dateTime`>1350296400 AND `dateTime`<1350301200) OR (`dateTime`>1350758700 AND `dateTime`<1350765000) OR (`dateTime`>1352101500 AND `dateTime`<1352108400) OR (`dateTime`>1354703400 AND `dateTime`<1354711200) OR (`dateTime`>1354735200 AND `dateTime`<1354740000) OR (`dateTime`>1354808400 AND `dateTime`<1354813200) OR (`dateTime`>1355184900 AND `dateTime`<1355189700) OR (`dateTime`>1355189700 AND `dateTime`<1355205300) OR (`dateTime`>1355205300 AND `dateTime`<1355230500) OR (`dateTime`>1356963900 AND `dateTime`<1356969900)) o LEFT JOIN `weewx_WH1080`.`archive` w ON w.`dateTime`=o.`dateTime` LEFT JOIN `pocasi-loucka.eu_old`.`archive` z ON z.`dateTime`=o.`dateTime` LEFT JOIN `loucka_reconstruction`.`archive` r ON r.`dateTime`=o.`dateTime` LEFT JOIN `loucka_reconstruction`.`archive` rp ON rp.`dateTime`=(o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0)) WHERE o.gap_id IS NOT NULL GROUP BY o.gap_id ORDER BY o.gap_id;
